import React from 'react'
import MsgHeading from '../Headings/MsgHeading'

function MsgHistory() {
  return (
    <div className=' border rounded-lg border-yellow-300 h-auto w-3/4 relative flex flex-col items-center justify-center'>
        <div className=" flex flex-col justify-around items-center">
        <MsgHeading title={"Date Time"} para={"date and time"} />
        
        <MsgHeading title={"Email"} para={"date and time"} />
        </div>
        
        
    </div>
  )
}

export default MsgHistory
